export interface CompletionEntry {
  name: string;
  summary: string;
}

const esc = (s: string) => s.replace(/'/g, `'\\''`).replace(/:/g, '\\:');

export function zshCompletion(cmds: CompletionEntry[]): string {
  const items = cmds.map((c) => `    '${esc(c.name)}:${c.summary.replace(/'/g, `'\\''`)}'`).join('\n');
  return `#compdef pf
# Generated by pf setup. Do not edit.
_pf() {
  local -a cmds
  cmds=(
${items}
  )
  if (( CURRENT == 2 )); then
    _describe 'pf command' cmds
  fi
}
compdef _pf pf
`;
}

export function bashCompletion(cmds: CompletionEntry[]): string {
  return `# Generated by pf setup. Do not edit.
_pf() {
  if [ "$COMP_CWORD" -eq 1 ]; then
    COMPREPLY=( $(compgen -W "${cmds.map((c) => c.name).join(' ')}" -- "\${COMP_WORDS[1]}") )
  fi
}
complete -F _pf pf
`;
}

export function fishCompletion(cmds: CompletionEntry[]): string {
  const lines = cmds.map(
    (c) => `complete -c pf -f -n '__fish_use_subcommand' -a '${c.name}' -d '${c.summary.replace(/'/g, `\\'`)}'`,
  );
  return `# Generated by pf setup. Do not edit.\n${lines.join('\n')}\n`;
}

export const RC_START = '# >>> pf >>>';
export const RC_END = '# <<< pf <<<';

/** Marked block appended to a shell rc file. */
export function rcBlock(shell: 'zsh' | 'bash', pfHomeDir: string): string {
  const file = `${pfHomeDir}/completions/pf.${shell}`;
  const body =
    shell === 'zsh'
      ? `autoload -Uz compinit; (( $+functions[compdef] )) || compinit\n[ -f "${file}" ] && source "${file}"`
      : `[ -f "${file}" ] && source "${file}"`;
  return `${RC_START}\n${body}\n${RC_END}\n`;
}

/** Remove the marked block from rc text. */
export function stripRcBlock(text: string): string {
  const re = new RegExp(`\\n?${RC_START}[\\s\\S]*?${RC_END}\\n?`, 'g');
  return text.replace(re, '\n');
}
